package com.langxi.babydiary.v3.notification.application;
import com.langxi.babydiary.v3.notification.infrastructure.PushSubscriptionMapper;import com.langxi.babydiary.v3.platform.application.V3Exception;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
@Service public class PushSubscriptionService {private final PushSubscriptionMapper mapper;private final String publicKey;public PushSubscriptionService(PushSubscriptionMapper mapper,@Value("${app.push.vapid-public-key:}")String publicKey){this.mapper=mapper;this.publicKey=publicKey;}
public String publicKey(){return publicKey==null||publicKey.isBlank()?null:publicKey;}
@Transactional public void subscribe(long accountId,String endpoint,String p256dh,String auth,String agent){validate(endpoint,p256dh,auth);mapper.upsert(accountId,hash(endpoint),endpoint,p256dh,auth,trim(agent,500));}
@Transactional public void unsubscribe(long accountId,String endpoint){if(endpoint==null||endpoint.isBlank())throw V3Exception.badRequest("PUSH_ENDPOINT_REQUIRED","推送地址不能为空");mapper.revoke(accountId,hash(endpoint));}
private void validate(String endpoint,String p256dh,String auth){if(endpoint==null||endpoint.isBlank()||endpoint.length()>4096)throw V3Exception.badRequest("PUSH_ENDPOINT_INVALID","推送地址无效");if(p256dh==null||p256dh.isBlank()||p256dh.length()>255||auth==null||auth.isBlank()||auth.length()>255)throw V3Exception.badRequest("PUSH_KEYS_INVALID","推送密钥无效");}
private byte[] hash(String value){try{return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));}catch(Exception e){throw new IllegalStateException(e);}}private String trim(String v,int max){return v==null?null:v.substring(0,Math.min(v.length(),max));}}
